def compute(vars):
    shares = vars["v1"]
    average_price = vars["v2"]
    total_spent = shares * average_price

    return {
        "value": total_spent,
        "trace": {
            "shares": shares,
            "average_price": average_price,
            "total_spent": total_spent,
            "output_meta": {
                "currency": "USD",
                "scale": "ones",
                "unit": "currency"
            }
        }
    }
